out=a.copy()
for br,bc in blocks:
    r=br
    for c in range(W):
        if bc-1<=c<=bc+1: continue
        if c in lines: continue  # line cells stay 2 at crossings
        out[r,c]=1
    for L in lines:
        if L==bc: continue
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==0 and dc==0: continue
                rr,rc=r+dr,L+dc
                if 0<=rr<H and 0<=rc<W:
                    out[rr,rc]=1
for row in out:
    print(' '.join(map(str,row)))
print([[int(x) for x in row] for row in out])
